import{_ as t,c as a,o as s,a3 as n}from"./chunks/framework.Dokpd4od.js";const g=JSON.parse('{"title":"CRM","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/crm/index.md","filePath":"master/sales/crm/index.md","lastUpdated":1793789158000}'),o={name:"master/sales/crm/index.md"};function r(i,e,l,d,p,h){return s(),a("div",null,e[0]||(e[0]=[n(`<h1 id="crm" tabindex="-1">CRM <a class="header-anchor" href="#crm" aria-label="Permalink to &quot;CRM&quot;">​</a></h1><p>CRM is where you keep track of people who may buy from you. You record an enquiry, qualify it, work it as an opportunity, send a quotation and close the deal as won or lost. The whole team sees one pipeline, so everyone knows what to do next.</p><blockquote><p><strong>In simple words:</strong> A lead is a possible customer. An opportunity is a deal you are working on. A won opportunity is a sale.</p></blockquote><p>Open the app from the <strong>CRM</strong> item in the main menu. It has five areas: <strong>Sales</strong>, <strong>Leads</strong>, <strong>Reporting</strong>, <strong>Configuration</strong> and <strong>Settings</strong>.</p><h2 id="the-flow-of-one-deal" tabindex="-1">The flow of one deal <a class="header-anchor" href="#the-flow-of-one-deal" aria-label="Permalink to &quot;The flow of one deal&quot;">​</a></h2><p>Here is one deal from start to finish. Sharma Textiles asks about <strong>ERP implementation for textile manufacturing unit</strong>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Enquiry arrives</span></span>
<span class="line"><span>      |</span></span>
<span class="line"><span>      v</span></span>
<span class="line"><span>   Lead  ----------------------------&gt; Lost (with a reason)</span></span>
<span class="line"><span>      |  Convert to Opportunity</span></span>
<span class="line"><span>      v</span></span>
<span class="line"><span>Opportunity: New &gt; Qualified &gt; Proposition &gt; Won</span></span>
<span class="line"><span>      |        |                              |</span></span>
<span class="line"><span>      |        +-- activities, notes, emails  |</span></span>
<span class="line"><span>      |                                       v</span></span>
<span class="line"><span>      +--&gt; New Quotation --&gt; Sales order --&gt; Invoice</span></span>
<span class="line"><span>      |</span></span>
<span class="line"><span>      +--&gt; Lost (with a reason)</span></span></code></pre></div><ol><li><strong>Lead.</strong> You create a lead, or a visitor rule creates one. See <a href="./acquire-leads/create-lead.html">Create a lead</a> and <a href="./acquire-leads/lead-generation.html">Generate leads from visitors</a>.</li><li><strong>Convert.</strong> You check the lead and click <strong>Convert to Opportunity</strong>. See <a href="./acquire-leads/convert-lead.html">Convert a lead</a>.</li><li><strong>Work the opportunity.</strong> You move the card across the stages and schedule follow-ups. See <a href="./pipeline/manage-opportunities.html">Manage opportunities</a> and <a href="./pipeline/schedule-activities.html">Schedule activities</a>.</li><li><strong>Quotation.</strong> You click <strong>New Quotation</strong> on the opportunity. See <a href="./pipeline/create-quotation.html">Create a quotation</a>.</li><li><strong>Close.</strong> The customer agrees, so you mark the opportunity as won. If not, you mark it as lost and give a reason. See <a href="./pipeline/mark-won-lost.html">Mark as won or lost</a>.</li></ol><p>A won deal continues in Sales as an order and an invoice. See <a href="./../sales/quotations-orders/">Quotations and orders</a> and <a href="./../sales/invoicing/order-to-invoice.html">Order to invoice</a>.</p><h2 id="settings-that-reveal-menus" tabindex="-1">Settings that reveal menus <a class="header-anchor" href="#settings-that-reveal-menus" aria-label="Permalink to &quot;Settings that reveal menus&quot;">​</a></h2><p>Some features stay hidden until you switch them on. Open <code>CRM → Settings → Manage CRM</code> or the other settings pages to change them. See <a href="./configuration/settings.html">CRM settings</a>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Where</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Lead Qualification</strong></td><td><code>Manage CRM</code></td><td>The <strong>Leads</strong> area and the <strong>New Lead</strong> button. Without it, new enquiries are created straight as opportunities.</td></tr><tr><td><strong>Recurring Revenue Plans</strong></td><td><code>Manage CRM</code></td><td>The <strong>Recurring Plans</strong> page and recurring revenue fields on opportunities.</td></tr><tr><td><strong>Salespeople in Multiple Teams</strong></td><td><code>Manage CRM</code></td><td>Lets one salesperson belong to more than one sales team.</td></tr><tr><td><strong>Automatic Lead Assignment</strong></td><td><code>Manage CRM</code></td><td>The <strong>Assign now</strong> button, <strong>Assignment Rules</strong> on each sales team, and assignment fields for team members.</td></tr><tr><td><strong>Visitors to Leads</strong></td><td><code>Manage Lead Generation</code></td><td>The <strong>Visitors to Leads Rules</strong> page. It needs the Website app to be installed.</td></tr><tr><td>Scoring options</td><td><code>Manage Lead Scoring</code></td><td>Which details feed the automatic probability.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you cannot find <strong>Leads</strong> in the menu, switch on <strong>Lead Qualification</strong> first.</p></div><h2 id="pages-in-this-module" tabindex="-1">Pages in this module <a class="header-anchor" href="#pages-in-this-module" aria-label="Permalink to &quot;Pages in this module&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>What it helps you do</th></tr></thead><tbody><tr><td><a href="./acquire-leads/">Acquire leads</a></td><td>Create leads, convert them to opportunities, merge duplicates and generate leads from website visitors.</td></tr><tr><td><a href="./pipeline/">Pipeline</a></td><td>Move opportunities across stages, schedule activities, send quotations and close deals.</td></tr><tr><td><a href="./assign-and-track/">Assign and track</a></td><td>Share leads between teams and salespeople, and score leads by chance of winning.</td></tr><tr><td><a href="./reporting/">Reporting</a></td><td>See forecasts, pipeline numbers, lead results and activities.</td></tr><tr><td><a href="./configuration/">Configuration</a></td><td>Set up stages, tags, lost reasons, recurring plans and partner levels.</td></tr></tbody></table><h2 id="records-you-share-with-other-apps" tabindex="-1">Records you share with other apps <a class="header-anchor" href="#records-you-share-with-other-apps" aria-label="Permalink to &quot;Records you share with other apps&quot;">​</a></h2><ul><li><strong>Customers</strong> live in Contacts. You pick them in CRM, you do not set them up here. See <a href="./../../getting-started/contacts/contacts.html">Contacts</a>.</li><li><strong>Quotations</strong> belong to Sales. CRM only starts them from an opportunity. See <a href="./../sales/">Sales overview</a>.</li><li><strong>Messages and activities</strong> use the shared tools described in <a href="./../../getting-started/chatter/introduction.html">Chatter</a> and <a href="./../../getting-started/activities.html">Activities</a>.</li><li><strong>Search, filter and group</strong> work the same way in every list. See <a href="./../../getting-started/search-filter-group.html">Search, filter and group records</a>.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./acquire-leads/create-lead.html">Create a lead</a></li><li><a href="./pipeline/manage-opportunities.html">Manage opportunities</a></li><li><a href="./configuration/settings.html">CRM settings</a></li><li><a href="./../sales/">Sales overview</a></li></ul>`,19)]))}const u=t(o,[["render",r]]);export{g as __pageData,u as default};
